changeSet.sql:
CREATE TABLE IF NOT EXISTS script_type (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  script_id INTEGER NOT NULL,
  type TEXT NOT NULL,
  UNIQUE(script_id, type)
);

CREATE TABLE IF NOT EXISTS processed_image (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  image_group_id INTEGER NOT NULL UNIQUE,
  character_id INTEGER NOT NULL,
  gallery_id INTEGER NOT NULL,
  original_path TEXT NOT NULL,
  selected_file TEXT NOT NULL,
  script_id INTEGER,
  confirmed_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);

CREATE INDEX IF NOT EXISTS idx_processed_character ON processed_image(character_id);
CREATE INDEX IF NOT EXISTS idx_processed_gallery ON processed_image(gallery_id);

CREATE TABLE IF NOT EXISTS similar_run (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  compared INTEGER NOT NULL,
  skipped INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS similar_group (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id INTEGER NOT NULL,
  kind TEXT NOT NULL,
  size INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_similar_group_run ON similar_group(run_id);

CREATE TABLE IF NOT EXISTS similar_member (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  group_id INTEGER NOT NULL,
  file_path TEXT NOT NULL,
  distance INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_similar_member_group ON similar_member(group_id);
